456.   <script>
457.     const quizForm = document.getElementById("quiz-form");
458.     const resultsPanel = document.getElementById("results-panel");
459.     const resultsMessage = document.getElementById("results-message");
460. 
461.     const answerKey = {
462.       "question-1": ["HTML", "CSS", "JavaScript"],
463.       "question-2": ["TypeScript", "Rust", "Java"],
464.       "question-3": ["Kotlin", "Swift"]
465.     };
466. 
467.     const questionNames = Object.keys(answerKey);
468. 
469.     function getInputs(questionName) {
470.       return Array.from(quizForm.querySelectorAll(`input[name="${questionName}"]`));
471.     }
472. 
473.     function getSelectedValues(questionName) {
474.       return getInputs(questionName)
475.         .filter((input) => input.checked)
476.         .map((input) => input.value)
477.         .sort();
478.     }
479. 
480.     function showGroupError(questionName, showError) {
481.       const error = document.getElementById(`${questionName}-error`);
482.       const inputs = getInputs(questionName);
483. 
484.       error.hidden = !showError;
485. 
486.       inputs.forEach((input) => {
487.         if (showError) {
488.           input.setAttribute("aria-invalid", "true");
489.         } else {
490.           input.removeAttribute("aria-invalid");
491.         }
492.       });
493.     }
494. 
495.     function validateSelections() {
496.       let firstInvalidInput = null;
497. 
498.       questionNames.forEach((questionName) => {
499.         const inputs = getInputs(questionName);
500.         const hasSelection = inputs.some((input) => input.checked);
501. 
502.         showGroupError(questionName, !hasSelection);
503. 
504.         if (!hasSelection && !firstInvalidInput) {
505.           firstInvalidInput = inputs[0];
506.         }
507.       });
508. 
509.       return firstInvalidInput;
510.     }
511. 
512.     questionNames.forEach((questionName) => {
513.       getInputs(questionName).forEach((input) => {
514.         input.addEventListener("change", () => {
515.           if (getSelectedValues(questionName).length > 0) {
516.             showGroupError(questionName, false);
517.           }
518.         });
519.       });
520.     });
521. 
522.     quizForm.addEventListener("submit", (event) => {
523.       event.preventDefault();
524. 
525.       const firstInvalidInput = validateSelections();
526. 
527.       if (firstInvalidInput) {
528.         resultsPanel.dataset.state = "error";
529.         resultsMessage.textContent = "Please answer every question before submitting the quiz.";
530.         firstInvalidInput.focus();
531.         return;
532.       }
533. 
534.       let score = 0;
535. 
536.       questionNames.forEach((questionName) => {
537.         const selected = getSelectedValues(questionName);
538.         const correct = [...answerKey[questionName]].sort();
539. 
540.         if (selected.length === correct.length && selected.every((value, index) => value === correct[index])) {
541.           score += 1;
542.         }
543.       });
544. 
545.       resultsPanel.dataset.state = "success";
546.       resultsMessage.textContent = `You scored ${score} out of ${questionNames.length}.`;
547.     });
548.   </script>
