  <script>
    const quizForm = document.getElementById("quiz-form");
    const resultsPanel = document.getElementById("results-panel");
    const resultsMessage = document.getElementById("results-message");

    const answerKey = {
      "question-1": ["HTML", "CSS", "JavaScript"],
      "question-2": ["TypeScript", "Rust", "Java"],
      "question-3": ["Kotlin", "Swift"]
    };

    const questionNames = Object.keys(answerKey);

    function getInputs(questionName) {
      return Array.from(quizForm.querySelectorAll(`input[name="${questionName}"]`));
    }

    function getSelectedValues(questionName) {
      return getInputs(questionName)
        .filter((input) => input.checked)
        .map((input) => input.value)
        .sort();
    }

    function showGroupError(questionName, showError) {
      const fieldset = quizForm.querySelector(`fieldset[data-question="${questionName}"]`);
      const error = document.getElementById(`${questionName}-error`);
      const inputs = getInputs(questionName);
      const baseDescription = fieldset.dataset.baseDescribedBy;

      error.hidden = !showError;
      fieldset.setAttribute("aria-describedby", showError ? `${baseDescription} ${questionName}-error` : baseDescription);

      inputs.forEach((input) => {
        if (showError) {
          input.setAttribute("aria-invalid", "true");
        } else {
          input.removeAttribute("aria-invalid");
        }
      });
    }

    function validateSelections() {
      let firstInvalidInput = null;

      questionNames.forEach((questionName) => {
        const inputs = getInputs(questionName);
        const hasSelection = inputs.some((input) => input.checked);

        showGroupError(questionName, !hasSelection);

        if (!hasSelection && !firstInvalidInput) {
          firstInvalidInput = inputs[0];
        }
      });

      return firstInvalidInput;
    }

    questionNames.forEach((questionName) => {
      getInputs(questionName).forEach((input) => {
        input.addEventListener("change", () => {
          if (getSelectedValues(questionName).length > 0) {
            showGroupError(questionName, false);
          }
        });
      });
    });

    quizForm.addEventListener("submit", (event) => {
      event.preventDefault();

      const firstInvalidInput = validateSelections();

      if (firstInvalidInput) {
        resultsPanel.dataset.state = "error";
        resultsMessage.textContent = "Please answer every question before submitting the quiz.";
        firstInvalidInput.focus();
        return;
      }

      let score = 0;

      questionNames.forEach((questionName) => {
        const selected = getSelectedValues(questionName);
        const correct = [...answerKey[questionName]].sort();

        if (selected.length === correct.length && selected.every((value, index) => value === correct[index])) {
          score += 1;
        }
      });

      resultsPanel.dataset.state = "success";
      resultsMessage.textContent = `You scored ${score} out of ${questionNames.length}.`;
    });
  </script>
