         radial-gradient(circle at top right, #dff7f0 0, transparent 25%),
         linear-gradient(180deg, #f8fbff 0%, var(--color-bg) 100%);
       color: var(--color-text);
     }

     a,
     button,
     input,
     label {
       -webkit-tap-highlight-color: transparent;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--color-text);
       color: var(--color-surface);
       text-decoration: none;
       transform: translateY(-220%);
       transition: transform 0.2s ease;
       z-index: 100;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     main {
       padding: 2rem 1rem 3rem;
     }

     .page-shell {
       max-width: 960px;
       margin: 0 auto;
     }

     .hero {
       display: grid;
       gap: 1rem;
       margin-bottom: 1.5rem;
     }

     .eyebrow {
       width: fit-content;
       margin: 0;
       padding: 0.45rem 0.8rem;
       border: 1px solid #b8c8ee;
       border-radius: 999px;
       background: #eef3ff;
       color: var(--color-accent-strong);
       font-size: 0.85rem;
       font-weight: 700;
       letter-spacing: 0.02em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2.2rem, 5vw, 4rem);
       line-height: 1.05;
       letter-spacing: -0.03em;
     }

     .intro {
       max-width: 42rem;
       margin: 0;
       color: var(--color-muted-text);
       font-size: 1.05rem;
       line-height: 1.6;
     }

     .quiz-card {
       padding: clamp(1.25rem, 3vw, 2rem);
       border: 1px solid #d4def3;
       border-radius: var(--radius-lg);
       background: rgba(255, 255, 255, 0.92);
       box-shadow: var(--shadow-soft);
       backdrop-filter: blur(12px);
     }

     form {
       display: grid;
       gap: 1.25rem;
     }

     .form-field {
       padding: 1.25rem;
       border: 1px solid #d6def0;
       border-radius: var(--radius-md);
       background: linear-gradient(180deg, #ffffff 0%, #f8faff 100%);
     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-width: 0;
     }

     legend {
       margin-bottom: 0.5rem;
       padding: 0;
       font-size: 1.1rem;
       font-weight: 700;
       line-height: 1.4;
     }

     .question-meta,
     .help-text,
     .error-text,
     .results-text {
       margin: 0;
       line-height: 1.5;
     }

     .question-meta {
       margin-bottom: 0.9rem;
       color: var(--color-muted-text);
       font-size: 0.95rem;
     }

     .help-text {
       margin-bottom: 1rem;
       color: var(--color-muted-text);
       font-size: 0.95rem;
     }

     .options {
       display: grid;
       grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
       gap: 0.85rem;
     }

     .option {
       position: relative;
       display: flex;
       align-items: center;
       gap: 0.85rem;
       min-height: 64px;
       padding: 1rem;
       border: 1px solid var(--color-border);
       border-radius: var(--radius-sm);
       background: var(--color-surface);
       cursor: pointer;
       transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
     }

     .option:hover {
       border-color: #9db2e8;
       transform: translateY(-1px);
     }

     .option:focus-within {
       border-color: var(--color-focus);
       box-shadow: 0 0 0 3px #dce6ff;
       outline: 2px solid transparent;
     }

     .option input {
       width: 1.15rem;
       height: 1.15rem;
       margin: 0;
       accent-color: var(--color-accent);
       flex: none;
     }

     .option-text {
       font-weight: 600;
       line-height: 1.35;
     }

     .option input:checked + .option-text {
       color: var(--color-accent-strong);
     }

     .error-text {
       margin-top: 0.9rem;
       color: var(--color-danger);
       font-weight: 600;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       align-items: center;
       gap: 1rem;
       padding-top: 0.25rem;
     }

     .submit-button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.4rem;
       background: linear-gradient(135deg, var(--color-accent) 0%, var(--color-accent-strong) 100%);
       color: var(--color-surface);
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(36, 71, 213, 0.25);
     }

     .submit-button:hover {
       filter: brightness(1.03);
     }

     .submit-button:focus-visible {
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     .results-panel {
       flex: 1 1 280px;
       min-height: 3.5rem;
       padding: 0.95rem 1rem;
       border: 1px solid #d6def0;
       border-radius: var(--radius-sm);
       background: var(--color-surface-alt);
     }

     .results-panel[data-state="success"] {
       border-color: #9fd6b3;
       background: #eefaf2;
     }

     .results-panel[data-state="error"] {
       border-color: #efb4ae;
       background: #fff4f2;
     }

     .results-text {
       color: var(--color-muted-text);
       font-weight: 600;
     }

     .results-panel[data-state="success"] .results-text {
       color: var(--color-success);
     }

     .results-panel[data-state="error"] .results-text {
       color: var(--color-danger);
     }

     @media (max-width: 640px) {
       main {
         padding-inline: 0.85rem;
       }

       .form-field {
         padding: 1rem;
       }

       .options {
         grid-template-columns: 1fr;
       }

       .actions {
         flex-direction: column;
         align-items: stretch;
       }

       .submit-button {
         width: 100%;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         scroll-behavior: auto;
         transition-duration: 0.01ms !important;
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
       }
     }

     @media (forced-colors: active) {
       body {
         background: Canvas;
       }

       .quiz-card,
       .form-field,
       .option,
       .results-panel {
         background: Canvas;
         border-color: ButtonBorder;
         box-shadow: none;
       }

       .submit-button {
         background: ButtonFace;
         color: ButtonText;
         border: 2px solid ButtonBorder;
         box-shadow: none;
       }

       .skip-link {
         background: Highlight;
         color: HighlightText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <main id="maincontent" tabindex="-1">
     <div class="page-shell">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Interactive quiz</p>
         <h1 id="page-title">Language Lab</h1>
         <p class="intro">
           Explore how different computer languages show up across the stack. Each question accepts multiple answers, so choose every option you believe is correct.
         </p>
       </section>

       <section class="quiz-card" aria-labelledby="quiz-heading">
         <h2 id="quiz-heading">Three quick questions</h2>

         <form id="quiz-form" novalidate>
           <div class="form-field">
             <fieldset aria-describedby="question-1-meta question-1-help" data-base-described-by="question-1-meta question-1-help" data-question="question-1">
               <legend>1. Which of these are commonly used to build web pages?</legend>
               <p class="question-meta" id="question-1-meta">Choose every language that is a standard part of a typical front-end stack.</p>
               <p id="question-1-help" class="help-text">Tip: Think about structure, presentation, and behavior in the browser.</p>
               <div class="options">
                 <label class="option">
                   <input type="checkbox" name="question-1" value="HTML">
                   <span class="option-text">HTML</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-1" value="CSS">
                   <span class="option-text">CSS</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-1" value="JavaScript">
                   <span class="option-text">JavaScript</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-1" value="SQL">
                   <span class="option-text">SQL</span>
                 </label>
               </div>
               <p id="question-1-error" class="error-text" hidden>Error: Select at least one answer for question 1.</p>
             </fieldset>
           </div>

           <div class="form-field">
             <fieldset aria-describedby="question-2-meta" data-base-described-by="question-2-meta" data-question="question-2">
               <legend>2. Which of these are statically typed languages?</legend>
               <p class="question-meta" id="question-2-meta">Pick every language that usually catches type issues before runtime.</p>
               <div class="options">
                 <label class="option">
                   <input type="checkbox" name="question-2" value="TypeScript">
                   <span class="option-text">TypeScript</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-2" value="Rust">
                   <span class="option-text">Rust</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-2" value="Ruby">
                   <span class="option-text">Ruby</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-2" value="Java">
                   <span class="option-text">Java</span>
                 </label>
               </div>
               <p id="question-2-error" class="error-text" hidden>Error: Select at least one answer for question 2.</p>
             </fieldset>
           </div>

           <div class="form-field">
             <fieldset aria-describedby="question-3-meta" data-base-described-by="question-3-meta" data-question="question-3">
               <legend>3. Which of these are widely used for native mobile app development?</legend>
               <p class="question-meta" id="question-3-meta">Choose the languages that are commonly associated with building iOS or Android apps.</p>
               <div class="options">
                 <label class="option">
                   <input type="checkbox" name="question-3" value="Kotlin">
                   <span class="option-text">Kotlin</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-3" value="Swift">
                   <span class="option-text">Swift</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-3" value="Go">
                   <span class="option-text">Go</span>
                 </label>
                 <label class="option">
                   <input type="checkbox" name="question-3" value="COBOL">
                   <span class="option-text">COBOL</span>
                 </label>
               </div>
               <p id="question-3-error" class="error-text" hidden>Error: Select at least one answer for question 3.</p>
             </fieldset>
           </div>

           <div class="actions">
             <button class="submit-button" type="submit">Submit quiz</button>
             <div class="results-panel" id="results-panel" data-state="idle">
               <p class="results-text" id="results-message" aria-live="polite">Your score will appear here after you submit.</p>
             </div>
           </div>
         </form>
       </section>
     </div>
   </main>

   <script>
     const quizForm = document.getElementById("quiz-form");
     const resultsPanel = document.getElementById("results-panel");
     const resultsMessage = document.getElementById("results-message");

     const answerKey = {
       "question-1": ["HTML", "CSS", "JavaScript"],
       "question-2": ["TypeScript", "Rust", "Java"],
       "question-3": ["Kotlin", "Swift"]
     };

     const questionNames = Object.keys(answerKey);

     function getInputs(questionName) {
       return Array.from(quizForm.querySelectorAll(`input[name="${questionName}"]`));
     }

     function getSelectedValues(questionName) {
       return getInputs(questionName)
         .filter((input) => input.checked)
         .map((input) => input.value)
         .sort();
     }

     function showGroupError(questionName, showError) {
       const fieldset = quizForm.querySelector(`fieldset[data-question="${questionName}"]`);
       const error = document.getElementById(`${questionName}-error`);
       const inputs = getInputs(questionName);
       const baseDescription = fieldset.dataset.baseDescribedBy;

       error.hidden = !showError;
       fieldset.setAttribute("aria-describedby", showError ? `${baseDescription} ${questionName}-error` : baseDescription);

       inputs.forEach((input) => {
         if (showError) {
           input.setAttribute("aria-invalid", "true");
         } else {
           input.removeAttribute("aria-invalid");
         }
       });
     }

     function validateSelections() {
       let firstInvalidInput = null;

       questionNames.forEach((questionName) => {
         const inputs = getInputs(questionName);
         const hasSelection = inputs.some((input) => input.checked);

         showGroupError(questionName, !hasSelection);

         if (!hasSelection && !firstInvalidInput) {
           firstInvalidInput = inputs[0];
         }
       });

       return firstInvalidInput;
     }

     questionNames.forEach((questionName) => {
       getInputs(questionName).forEach((input) => {
         input.addEventListener("change", () => {
           if (getSelectedValues(questionName).length > 0) {
             showGroupError(questionName, false);
           }
         });
       });
     });

     quizForm.addEventListener("submit", (event) => {
       event.preventDefault();

       const firstInvalidInput = validateSelections();

       if (firstInvalidInput) {
         resultsPanel.dataset.state = "error";
         resultsMessage.textContent = "Please answer every question before submitting the quiz.";
         firstInvalidInput.focus();
         return;
       }

       let score = 0;

       questionNames.forEach((questionName) => {
         const selected = getSelectedValues(questionName);
         const correct = [...answerKey[questionName]].sort();

         if (selected.length === correct.length && selected.every((value, index) => value === correct[index])) {
           score += 1;
         }
       });

       resultsPanel.dataset.state = "success";
       resultsMessage.textContent = `You scored ${score} out of ${questionNames.length}.`;
     });
   </script>
 </body>
 </html>

')
